t.script:
const C=['#f0b429','#3fb950','#58a6ff','#f85149','#a371f7','#ff9500'];
const MAR=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
let G={B:[],CH:{},tab:0};
function fmt(n){if(Math.abs(n)>=1e6)return(n/1e6).toFixed(2)+'M';if(Math.abs(n)>=1e3)return(n/1e3).toFixed(1)+'K';return Math.round(n).toLocaleString()}
function fs(n){return 'ر.س '+fmt(n)}
function fp(n){return parseFloat(n).toFixed(1)+'%'}
function dt(v){const c=v>=0?'tg':'tr',i=v>=0?'▲':'▼';return ''+i+' '+Math.abs(v).toFixed(1)+'%'}
function step(m){document.getElementById('ls').textContent=m}
async function rpc(model,method,args=[],kw={}){
  const r=await fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',method:'call',id:Date.now(),params:{model,method,args,kwargs:kw}})});
  const d=await r.json();if(d.error)throw new Error(d.error.data?.message);return d.result;
}
async function fetchB(cid,df,dt2){
  const mo={};let off=0;
  while(true){
    const o=await rpc('pos.order','search_read',[[['config_id','=',cid],['state','in',['done','invoiced']],['date_order','>=',df],['date_order','<=',dt2]]],{fields:['date_order','amount_total'],limit:5000,offset:off});
    if(!o.length)break;
    o.forEach(x=>{const m=x.date_order.slice(0,7);mo[m]=(mo[m]||0)+x.amount_total;});
    off+=o.length;if(o.length<5000)break;
  }
  return mo;
}
async function init(){
  document.getElementById('ld').style.display='flex';
  document.getElementById('app').style.display='none';
  Object.values(G.CH).forEach(c=>c.destroy());G.CH={};G.B=[];
  try{
    step('تحميل إعدادات الفروع...');
    const cfgs=await rpc('pos.config','search_read',[[['active','=',true]]],{fields:['id','name'],limit:50});
    const now=new Date();
    const from=new Date(now.getFullYear(),now.getMonth()-11,1);
    const df=from.toISOString().split('T')[0];
    const dt2=now.toISOString().split('T')[0];
    const m12=[];for(let i=0;i<12;i++){const d=new Date(from.getFullYear(),from.getMonth()+i,1);m12.push(d.toISOString().slice(0,7));}
    const ml=m12.map(m=>{const p=m.split('-');return MAR[parseInt(p[1])-1]+' '+p[0].slice(2)});
    const CR=0.225;const BD=[];
    for(let i=0;iMath.round(mo[m]||0));
      const tr=ma.reduce((s,v)=>s+v,0);if(tr===0)continue;
      const q3=ma.slice(6,9).reduce((s,v)=>s+v,0);
      const q4=ma.slice(9,12).reduce((s,v)=>s+v,0);
      const q1=ma.slice(0,3).reduce((s,v)=>s+v,0);
      const qoq=q3>0?parseFloat(((q4-q3)/q3*100).toFixed(1)):0;
      const yoy=q1>0?parseFloat(((q4-q1)/q1*100).toFixed(1)):0;
      const cogs=Math.round(tr*CR);const gp=tr-cogs;const gm=parseFloat((gp/tr*100).toFixed(1));
      BD.push({name:c.name,ma,tr,cogs,gp,gm,qoq,yoy});
    }
    BD.sort((a,b)=>b.tr-a.tr);
    const mx=BD[0]?.tr||1;
    BD.forEach(b=>{b.sc=Math.round((b.tr/mx)*50+(b.gm/80)*30+(b.qoq>0?Math.min(b.qoq/10,1)*20:0));});
    G.B=BD;G.m12=m12;G.ml=ml;
    document.getElementById('pb').textContent='📅 '+df.slice(0,7)+' – '+dt2.slice(0,7);
    document.getElementById('tp').textContent='البيانات: '+df.slice(0,7)+' – '+dt2.slice(0,7);
    kpis();renderTab(0);
    document.getElementById('ld').style.display='none';
    document.getElementById('app').style.display='block';
  }catch(e){step('خطأ: '+e.message);console.error(e);}
}
function kpis(){
  const B=G.B;
  const tr=B.reduce((s,b)=>s+b.tr,0);
  const tg=B.reduce((s,b)=>s+b.gp,0);
  document.getElementById('k1').textContent=fs(tr);
  document.getElementById('k1s').textContent=B.length+' فروع';
  document.getElementById('k2').textContent=fs(tg);
  document.getElementById('k2s').textContent=fp(tg/tr*100)+' هامش إجمالي';
  document.getElementById('k3').textContent=B[0]?.name||'—';
  document.getElementById('k3s').textContent=B[0]?fs(B[0].tr):'—';
  document.getElementById('k4').textContent=B.length;
  document.getElementById('k4s').textContent='فرع نشط';
}
function sw(i){
  document.querySelectorAll('.tab').forEach((b,j)=>b.classList.toggle('active',i===j));
  document.querySelectorAll('.pane').forEach((p,j)=>p.classList.toggle('active',i===j));
  G.tab=i;renderTab(i);
}
function renderTab(i){if(i===0)bOv();else if(i===1)bVH();else if(i===2)bPr();else if(i===3)bFc();else if(i===4)bRp();}
function mk(id,cfg){const c=document.getElementById(id);if(!c)return;if(G.CH[id])G.CH[id].destroy();G.CH[id]=new Chart(c,cfg);return G.CH[id];}
const BASE={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}}};
function bOv(){
  if(G.CH['cm'])return;
  const B=G.B,ML=G.ml;
  document.getElementById('lg0').innerHTML=B.map((b,i)=>'
'+b.name+'').join('');
  mk('cm',{type:'line',data:{labels:ML,datasets:B.map((b,i)=>({label:b.name,data:b.ma,borderColor:C[i%6],backgroundColor:C[i%6]+'15',borderWidth:2,pointRadius:3,tension:0.4,fill:false}))},options:{...BASE,scales:{x:{ticks:{color:'#8b949e',font:{size:10}},grid:{color:'rgba(48,54,61,0.6)'}},y:{ticks:{color:'#8b949e',callback:v=>fmt(v),font:{size:10}},grid:{color:'rgba(48,54,61,0.6)'}}}}});
  mk('ct',{type:'bar',data:{labels:B.map(b=>b.name),datasets:[{data:B.map(b=>b.tr),backgroundColor:C,borderRadius:5,borderSkipped:false}]},options:{...BASE,scales:{x:{ticks:{color:'#8b949e',font:{size:10}},grid:{display:false}},y:{ticks:{color:'#8b949e',callback:v=>fmt(v),font:{size:10}},grid:{color:'rgba(48,54,61,0.6)'}}}}});
  mk('cp',{type:'doughnut',data:{labels:B.map(b=>b.name),datasets:[{data:B.map(b=>b.tr),backgroundColor:C,borderWidth:0}]},options:{...BASE,cutout:'65%',plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>ctx.label+': '+fs(ctx.raw)}}}}});
}
function bVH(){
  if(G.CH['ch'])return;
  const B=G.B;
  document.getElementById('tv').innerHTML='
الفرعالإيراداتتكلفة البضاعة %هامش إجمالي %QoQYoY'+B.map((b,i)=>'
'+b.name+''+fs(b.tr)+''+fp(22.5)+''+fp(b.gm)+''+dt(b.qoq)+''+(b.yoy===0?'جديد':dt(b.yoy))+'').join('')+'';
  mk('ch',{type:'bar',data:{labels:B.map(b=>b.name),datasets:[{label:'QoQ',data:B.map(b=>b.qoq),backgroundColor:'#f0b429',borderRadius:4},{label:'YoY',data:B.map(b=>b.yoy===0?null:b.yoy),backgroundColor:'#58a6ff',borderRadius:4}]},options:{...BASE,scales:{x:{ticks:{color:'#8b949e',font:{size:10}},grid:{color:'rgba(48,54,61,0.5)'}},y:{ticks:{color:'#8b949e',callback:v=>v+'%',font:{size:10}},grid:{color:'rgba(48,54,61,0.5)'},afterDataLimits:s=>{s.min=Math.min(s.min,-10);s.max=Math.max(s.max,15)}}}}});
  const an=B.filter(b=>b.qoq<-5||b.yoy<-5);
  document.getElementById('an').innerHTML=an.length===0?'
✅ لا توجد شواذ كبيرة':an.map(b=>'

⚠️ '+b.name+''+(b.qoq<-5?'
QoQ'+fp(b.qoq)+' ↓':'')+(b.yoy<-5?'
YoY'+fp(b.yoy)+' ↓':'')+'
الإيرادات'+fs(b.tr)+'').join('');
}
function bPr(){
  if(G.CH['cmar'])return;
  const B=G.B;
  mk('cmar',{type:'bar',data:{labels:B.map(b=>b.name),datasets:[{data:B.map(b=>parseFloat(b.gm.toFixed(1))),backgroundColor:B.map(b=>b.gm>=75?'#3fb950':b.gm>=70?'#f0b429':'#f85149'),borderRadius:5,indexAxis:'y'}]},options:{...BASE,indexAxis:'y',scales:{x:{ticks:{color:'#8b949e',callback:v=>v+'%',font:{size:10}},grid:{color:'rgba(48,54,61,0.5)'}},y:{ticks:{color:'#8b949e',font:{size:10}},grid:{display:false}}}}});
  document.getElementById('be').innerHTML=B.map(b=>{const be=Math.round(b.tr*0.13/12/(b.gm/100));const avg=Math.round(b.tr/12);return '
'+b.name+''+fs(be)+'/شهر'+(avg>=be?'✓ تجاوز':'✗ لم يصل')+'';}).join('');
  document.getElementById('tp2').innerHTML='
الفرعالإيراداتتكلفة البضاعةإجمالي الربحهامش إجماليQoQ'+B.map(b=>'
'+b.name+''+fs(b.tr)+''+fs(b.cogs)+''+fs(b.gp)+''+fp(b.gm)+''+dt(b.qoq)+'').join('')+'';
}
function bFc(){
  if(G.CH['cf'])return;
  const B=G.B,ML=G.ml;
  const agg=ML.map((_,i)=>B.reduce((s,b)=>s+(b.ma[i]||0),0));
  const l3=agg.slice(-3);const tr=(l3[2]-l3[0])/2;const fc=Math.max(Math.round(l3[2]+tr*0.5),0);
  mk('cf',{type:'line',data:{labels:[...ML,'Q التالي (توقع)'],datasets:[{label:'فعلي',data:[...agg,null],borderColor:'#3fb950',backgroundColor:'rgba(63,185,80,0.08)',borderWidth:2,pointRadius:4,tension:0.4,fill:true},{label:'توقع',data:[...Array(12).fill(null),fc],borderColor:'#f0b429',borderDash:[6,4],borderWidth:2,pointRadius:8,pointStyle:'triangle',fill:false}]},options:{...BASE,scales:{x:{ticks:{color:'#8b949e',font:{size:10}},grid:{color:'rgba(48,54,61,0.5)'}},y:{ticks:{color:'#8b949e',callback:v=>fmt(v),font:{size:10}},grid:{color:'rgba(48,54,61,0.5)'}}}}});
  const srt=[...B].sort((a,b2)=>b2.sc-a.sc);
  document.getElementById('rk').innerHTML='
'+srt.map((b,i)=>'

'+(i+1)+'
'+b.name+'


'+b.sc+' pts'+dt(b.qoq)+'').join('')+'';
}
function bRp(){
  const B=[...G.B].sort((a,b2)=>b2.sc-a.sc);
  const md=['🥇','🥈','🥉'];
  document.getElementById('t3').innerHTML=B.slice(0,3).map((b,i)=>'

'+md[i]+'

'+b.name+'
الإيرادات: '+fs(b.tr)+' | هامش: '+fp(b.gm)+' | QoQ: '+dt(b.qoq)+'').join('');
  document.getElementById('b3').innerHTML=B.slice(-Math.min(2,B.length)).reverse().map((b,i)=>'

'+(i+1)+'

'+b.name+'
'+(b.qoq<0?'تراجع QoQ '+dt(b.qoq)+' — ':'')+' الإيرادات: '+fs(b.tr)+' | هامش: '+fp(b.gm)+'').join('');
  document.getElementById('recs').innerHTML='

🎯 تعزيز الفروع الأعلى نمواً
الفروع بنمو QoQ إيجابي تستحق مزيداً من التسويق والمخزون.

⚠️ مراجعة الفروع المتراجعة
الفروع بنمو QoQ سلبي تحتاج دراسة تشغيلية فورية.

💰 تحسين هامش التكلفة
التفاوض الموحّد مع الموردين يخفض COGS ويحسّن الهامش.';
  const tr=G.B.reduce((s,b)=>s+b.tr,0),tg=G.B.reduce((s,b)=>s+b.gp,0);
  document.getElementById('ex').innerHTML='📋 الملخص التنفيذي

حققت المنشأة إجمالي إيرادات '+fs(tr)+' عبر '+G.B.length+' فروع، بإجمالي ربح '+fs(tg)+' وهامش إجمالي '+fp(tg/tr*100)+'. يتصدر '+G.B[0]?.name+' القائمة. البيانات محدّثة لحظياً من Odoo POS.';
}
init();
